"""Writes reports/M2E_CYCLE_COVERAGE_REPORT.md from reports/m2e_data/<cycle>/coverage.json (no hand-typed numbers)."""
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); PE = os.path.dirname(HERE); sys.path.insert(0, os.path.join(PE, 'python'))
from pe import forensics as F
D = os.path.join(PE, 'reports', 'm2e_data'); K = [F.cycle_key(*c) for c in F.CYCLES]; C = {k: json.load(open(os.path.join(D, k, 'coverage.json'))) for k in K}
def row(label, f, note=''): return f"| {label} | " + ' | '.join(f(C[k]) for k in K) + f" | {note} |"
def n(x): return f'{x:,}'
L = ['# M2-E — Cycle coverage report (Stage 2: source audit before any result)', '',
     '**Frozen cycles (selected before any grouping, `e06a711e`; not substituted):** NIFTY 2026-06-30 · SENSEX 2026-07-16.  Generated by `tools/m2e_coverage_report.py` from `reports/m2e_data/<cycle>/coverage.json`.', '',
     '**Verdict:** both cycles have complete fill, parent-metadata, lineage, closing-batch and wing/body coverage. **Historical option marks are NOT available in this environment** (see §4): no mark is used or substituted, unrealized P&L is `NA`. Neither cycle contains a position that expired unclosed.', '',
     '| Item | NIFTY 2026-06-30 | SENSEX 2026-07-16 | Note |', '|---|---:|---:|---|',
     row('Raw fills', lambda c: n(c['fills']['raw_fill_count']), 'source rows of `Trades_GKOHNP140.csv` for the cycle'),
     row('Unique parent orders', lambda c: n(c['fills']['unique_parent_orders'])),
     row('Opening fills (any opening quantity)', lambda c: n(c['fills']['opening_fills'])),
     row('Closing fills (any closing quantity)', lambda c: n(c['fills']['closing_fills'])),
     row('Fills with both opening and closing quantity', lambda c: n(c['fills']['fills_with_both_opening_and_closing_quantity']), 'a reversing fill'),
     row('Opening units / closing units', lambda c: f"{n(c['fills']['opening_units'])} / {n(c['fills']['closing_units'])}", 'equal: every unit opened was closed'),
     row('Position episodes', lambda c: n(c['episodes']['episode_count'])),
     row('Episode terminal status', lambda c: ', '.join(f'{k} {v}' for k, v in sorted(c['episodes']['terminal_status'].items()))),
     row('Episodes started by reversal', lambda c: str(c['episodes']['started_by_reversal'])),
     row('Expired-unclosed episodes', lambda c: str(c['episodes']['expired_unclosed']), '**none: that case type is UNAVAILABLE in both cycles**'),
     row('Contracts traded', lambda c: str(c['historical_marks']['contracts_traded'])),
     row('Historical mark coverage', lambda c: 'NOT COMPUTED (source absent)', 'see §4'),
     row('Opening units classified by module tag (body short / wing long)', lambda c: f"{n(c['role_classification']['opening_units_classified_by_tag'])} of {n(c['role_classification']['opening_units_total'])} ({c['role_classification']['opening_units_classified_by_tag'] / c['role_classification']['opening_units_total']:.1%})", 'rest UNCLASSIFIED, visible in V6'),
     row('Order metadata (entry minute, app key, order no., algo id, requested qty)', lambda c: 'complete' if not any(c['order_metadata']['field_missing'].values()) else 'INCOMPLETE: ' + str(c['order_metadata']['field_missing']), 'per-field table in §3'),
     row('Parents without metadata', lambda c: str(c['missing_or_ambiguous']['parents_without_metadata'])),
     row('Partially-filled fills (status `PartiallyFilled`)', lambda c: str(c['missing_or_ambiguous']['partially_filled_fills'])),
     row('Duplicate-flagged fills', lambda c: str(c['fills']['duplicate_flagged'])),
     row('Parents with MIXED role (opening and closing quantity)', lambda c: f"{c['missing_or_ambiguous']['parents_with_mixed_role']} ({', '.join(c['fills']['mixed_parent_ids'])})", 'kept; analysed once as a closing parent and once as an opening parent'),
     row('Unattributable closing portions / parents in several closing streams', lambda c: f"{c['missing_or_ambiguous']['unattributable_closing_portions']} / {c['missing_or_ambiguous']['closing_parents_in_multiple_streams']}"),
     row('Opening wing items with no W1 candidate (W1_S60)', lambda c: f"{c['missing_or_ambiguous']['wing_items_without_W1_candidate']} ({c['missing_or_ambiguous']['wing_items_without_W1_S60_candidate']})", 'ambiguity preserved, not forced'),
     row('Opening body items with no wing (W1) (W1_S60)', lambda c: f"{c['missing_or_ambiguous']['body_items_without_wing_W1']} ({c['missing_or_ambiguous']['body_items_without_wing_W1_S60']})")]
L += ['', '## 1. Sessions: D-1 and D0 coverage (IST sessions)', '', '| Cycle | Session (IST) | Role | Fills | Parents | Opening units | Closing units | First fill (IST) | Last fill (IST) | Instruments | Episodes started / ended |', '|---|---|---|---:|---:|---:|---:|---|---|---:|---|']
for k in K:
    for s, v in C[k]['d1_d0'].items(): L.append(f"| {k} | {s} | {v['d_label']} | {v['fills']} | {v['parents']} | {n(v['opening_units'])} | {n(v['closing_units'])} | {v['first_fill_ist']} | {v['last_fill_ist']} | {v['instruments']} | {v['episodes_started']} / {v['episodes_ended']} |")
L += ['', 'Both D-1 and D0 sessions are present in both cycles. D-1 inventory carried into D0 is in `session_carry.tsv` and drawn as the boundary in V1.', '',
      '## 2. Role classification coverage (module tag only)', '',
      'Roles here are **module-tag labels**, not ownership: body = short `num` opening, wing = long `h_` opening (M2-D rules). Everything else is shown as `UNCLASSIFIED(tag, side)` and stays visible.', '', '| Opening unit class | ' + ' | '.join(K) + ' |', '|---|' + '---:|' * len(K)]
for cls in sorted({x for k in K for x in C[k]['role_classification']['opening_units_by_tag_role']}): L.append(f'| {cls} | ' + ' | '.join(n(C[k]['role_classification']['opening_units_by_tag_role'].get(cls, 0)) for k in K) + ' |')
L += ['', '**Closing units excluded from the M2-D tag-based role analysis** (closing-fill tag / episode direction), per cycle:', '', '| Scope exclusion (units) | ' + ' | '.join(K) + ' |', '|---|' + '---:|' * len(K)]
for cls in sorted({x for k in K for x in C[k]['role_classification']['m2d_tagged_scope_exclusions_units']}): L.append(f'| {cls} | ' + ' | '.join(n(C[k]['role_classification']['m2d_tagged_scope_exclusions_units'].get(cls, 0)) for k in K) + ' |')
L += ['', 'A position absent from the role-specific analysis must **not** be read as having lacked a wing.', '', '## 3. Order metadata availability', '', '| Field | ' + ' | '.join(f'{k} (parents with field / parents)' for k in K) + ' |', '|---|' + '---:|' * len(K)]
for fld in C[K[0]]['order_metadata']['field_available']: L.append(f'| {fld} | ' + ' | '.join(f"{C[k]['order_metadata']['field_available'][fld]} / {C[k]['order_metadata']['parents']}" for k in K) + ' |')
L += ['', '## 4. Historical marks (missing source — reported, not replaced)', '']
for k in K:
    m = C[k]['historical_marks']; L += [f"* **{k}**: contracts traded {m['contracts_traded']}; raw 1-minute option bars present here: **{m['source_present_in_this_environment']}** (`{m['source_env_var']}` unset / folder absent). Status: {m['historical_mark_status']}. Recorded at cycle selection (a prior measurement, not reproducible here, not used for any M2-E number): option-mark availability {m['recorded_at_cycle_selection_time']['C4_option_marks']}. Prices used in M2-E: {m['prices_used_in_M2E']}."]
L += ['', 'Consequences: no unrealized-P&L chart, no mark-to-market inventory value, no interpolated price. Execution prices (fills) and market marks are kept as different things; marks = missing source.', '',
      '## 5. TP-03 overlay (V3 only)', '', 'TP-03 publishes entry-window rows and per-parent `OFF_WINDOW_ACTION` / `INITIAL_ENTRY` classes for **body-short** parents only; it publishes **no per-parent window id**. M2-E draws the TP-03 windows as a separate overlay and labels listed parents as TP-03 classes; unlisted parents are labelled `NOT_LISTED_BY_TP03_AS_OFF_WINDOW`, never "in window".', '',
      '| Cycle | Parents listed by TP-03 (off-window or initial entry) |', '|---|---:|'] + [f"| {k} | {C[k]['tp03_overlay']['parents_listed_off_window_or_initial']} |" for k in K]
L += ['', '## 6. Reconciliation performed during assembly (all passed)', '', '* Cycle-only lineage (events, episodes, OA, CP) **identical** to the full-ledger lineage restricted to the cycle instruments.', '* M2-C: all six committed batch/member/portion files, filtered to the cycle, are **byte-equal** to a per-cycle recomputation with the committed engine.', '* M2-D: committed items and all five link views, filtered to the cycle, equal a per-cycle recomputation.',
      '* Independent re-derivation from raw `side × quantity` only (no lineage): signed position per instrument equals the V1 series after every fill; opening + closing quantity = fill quantity for every fill; opened = closed units; final position flat; every fill lies inside 09:14–15:31 IST (rules out UTC read as IST).', '', '## 7. Missing sources (summary)', '', '| Source | Status | Effect |', '|---|---|---|', '| Raw 1-minute option/index bars (`ALGO8_MARKET_DIR`) | absent in this environment | no marks, no unrealized P&L, no price context charts |', '| TP-03 per-parent window id | not published | window attribution shown only as overlay + classes |', '| Expired-unclosed positions | none exist in either frozen cycle | that case study UNAVAILABLE (not borrowed from another cycle) |', '| Reversal in SENSEX | none | reversal case UNAVAILABLE for SENSEX; available for NIFTY |']
open(os.path.join(PE, 'reports', 'M2E_CYCLE_COVERAGE_REPORT.md'), 'w').write('\n'.join(L) + '\n'); print('\n'.join(L)[:1800])
